5	namespace AtrioTeam\DigitalHub\Tags\Filament;
6	
7	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
8	use AtrioTeam\DigitalHub\Tags\Models\Tag;
9	use Closure;
10	use Filament\Forms\Components\Select;
11	use Illuminate\Database\Eloquent\Builder;
12	
13	/**
14	 * Select dei tag associabili, con vincolo rigido: mostra solo i tag il cui
15	 * gruppo è filtrato per l'entità data e per il target dato (entity|asset).
16	 * Ogni opzione mostra la categoria di appartenenza nell'etichetta
17	 * (es. "Materiale › Legno"). Condiviso fra i form delle entità e il picker
18	 * degli asset nell'AssetManager.
19	 */
20	class TagPicker
21	{
22	    /**
23	     * Picker legato alla relazione `tags` del record del form (entità che usa
24	     * HasTags): Filament sincronizza da sé il pivot `taggables`.
25	     *
26	     * Con relationship() Filament costruisce le opzioni dalla query della
27	     * relazione: la label si personalizza via getOptionLabelFromRecordUsing()
28	     * e il filtro (entity_type, target) via modifyQueryUsing().
29	     *
30	     * `$scopeGroupsUsing` (opzionale) restringe ulteriormente i gruppi: riceve
31	     * la query dei TagGroup come parametro nominato `query` e viene valutata da
32	     * Filament, quindi supporta l'injection dei parametri di contesto (es.
33	     * `$livewire`). Permette all'app vincoli propri (es. la Destinazione
34	     * Category1) senza che il package li conosca.
35	     */
36	    public static function make(string $entityAlias, TagTarget $target, ?Closure $scopeGroupsUsing = null): Select
37	    {
38	        return self::base()
39	            // HasTags espone tags() come MorphToMany: Filament sincronizza il pivot.
40	            // I tag si gestiscono dalla loro resource, qui si associano solo esistenti.
41	            ->relationship(
42	                name: 'tags',
43	                titleAttribute: 'name',
44	                modifyQueryUsing: fn (Builder $query, Select $component): Builder => self::scopeToGroup(
45	                    $query,
46	                    $entityAlias,
47	                    $target,
48	                    $scopeGroupsUsing === null ? null : function (Builder $groupQuery) use ($component, $scopeGroupsUsing): void {
49	                        $component->evaluate($scopeGroupsUsing, ['query' => $groupQuery]);
50	                    },
51	                ),
52	            )
53	            ->getOptionLabelFromRecordUsing(fn (Tag $record): string => self::optionLabel($record));
54	    }
55	
56	    /**
57	     * Picker "standalone" (senza relationship): lo stato è un array di id tag.
58	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
59	     * dove fill/sync sono gestiti a mano dal chiamante.
60	     */
61	    public static function makeStandalone(string $entityAlias, TagTarget $target): Select
62	    {
63	        return self::base()
64	            ->options(fn (): array => self::groupedOptions($entityAlias, $target));
65	    }
66	
67	    private static function base(): Select
68	    {
69	        return Select::make('tags')
70	            ->label(__('digital-hub::tag.model_plural'))
71	            ->multiple()
72	            ->searchable()
73	            ->preload();
74	    }
75	
76	    /**
77	     * Restringe la query dei tag ai soli gruppi filtrati per entità e target,
78	     * più l'eventuale vincolo aggiuntivo sui gruppi passato dal chiamante.
79	     *
80	     * @param Builder<Tag> $query
81	     * @param (Closure(Builder<\Illuminate\Database\Eloquent\Model>): void)|null $scopeGroups query dei TagGroup
82	     * @return Builder<Tag>
83	     */
84	    private static function scopeToGroup(Builder $query, string $entityAlias, TagTarget $target, ?Closure $scopeGroups = null): Builder
85	    {
86	        return $query->whereHas('category.group', function (Builder $groupQuery) use ($entityAlias, $target, $scopeGroups) {
87	            $groupQuery
88	                ->where('entity_type', $entityAlias)
89	                ->where('target', $target->value);
90	
91	            if ($scopeGroups !== null) {
92	                $scopeGroups($groupQuery);
93	            }
94	        });
95	    }
96	
97	    /**
98	     * Etichetta con categoria di appartenenza in testa (es. "Materiale › Legno").
99	     */
100	    private static function optionLabel(Tag $tag): string
101	    {
102	        $category = $tag->category !== null ? (string) $tag->category->name : (string) __('digital-hub::tag.ungrouped');
103	
104	        return $category . ' › ' . (string) $tag->name;
105	    }
106	
107	    /**
108	     * Opzioni per la variante standalone: id => "Categoria › Tag".
109	     * Solo i tag dei gruppi (entity_type, target).
110	     *
111	     * @return array<int, string>
112	     */
113	    private static function groupedOptions(string $entityAlias, TagTarget $target): array
114	    {
115	        $options = [];
116	
117	        $tags = self::scopeToGroup(Tag::query(), $entityAlias, $target)
118	            ->with('category')
119	            ->get();
120	
121	        foreach ($tags as $tag) {
122	            $options[(int) $tag->id] = self::optionLabel($tag);
123	        }
124	
125	        return $options;
126	    }
127	}
